import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_forward_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size,
    int in_channels, int out_channels,
    int in_depth, int in_height, int in_width,
    int kernel_size, int stride, int padding, int dilation,
    int out_depth, int out_height, int out_width
) {
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride_grid = blockDim.x * gridDim.x;

    for (int i = tid; i < total_elements; i += stride_grid) {
        int n = i / (out_channels * out_depth * out_height * out_width);
        int rem = i % (out_channels * out_depth * out_height * out_width);
        int oc = rem / (out_depth * out_height * out_width);
        rem = rem % (out_depth * out_height * out_width);
        int od = rem / (out_height * out_width);
        rem = rem % (out_height * out_width);
        int oh = rem / out_width;
        int ow = rem % out_width;

        float sum = 0.0f;

        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int id = od - (kd * dilation - padding);
                    if (id < 0 || id % stride != 0) continue;
                    id = id / stride;

                    int ih = oh - (kh * dilation - padding);
                    if (ih < 0 || ih % stride != 0) continue;
                    ih = ih / stride;

                    int iw = ow - (kw * dilation - padding);
                    if (iw < 0 || iw % stride != 0) continue;
                    iw = iw / stride;

                    if (id >= 0 && id < in_depth &&
                        ih >= 0 && ih < in_height &&
                        iw >= 0 && iw < in_width) {

                        for (int ic = 0; ic < in_channels; ++ic) {
                            int input_idx = n * in_channels * in_depth * in_height * in_width +
                                        ic * in_depth * in_height * in_width +
                                        id * in_height * in_width +
                                        ih * in_width +
                                        iw;

                            int weight_idx = ic * out_channels * kernel_size * kernel_size * kernel_size +
                                            oc * kernel_size * kernel_size * kernel_size +
                                            kd * kernel_size * kernel_size +
                                            kh * kernel_size +
                                            kw;

                            sum += input[input_idx] * weight[weight_idx];
                        }
                    }
                }
            }
        }

        if (bias) {
            sum += bias[oc];
        }

        output[i] = sum;
    }
}

torch::Tensor conv_transpose3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);
    int out_channels = weight.size(1);

    int out_depth = (in_depth - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;
    int out_height = (in_height - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;
    int out_width = (in_width - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;

    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, input.options());

    int total_elements = output.numel();
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    conv_transpose3d_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels, out_channels,
        in_depth, in_height, in_width,
        kernel_size, stride, padding, dilation,
        out_depth, out_height, out_width
    );

    return output;
}
"""

conv_transpose3d_cpp_source = "torch::Tensor conv_transpose3d_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int kernel_size, int stride, int padding, int dilation);"

conv_transpose3d = load_inline(
    name='conv_transpose3d',
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_forward_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self.weight = nn.Parameter(torch.Tensor(
            in_channels,
            out_channels,
            kernel_size,
            kernel_size,
            kernel_size
        ))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
            fan_in = in_channels * kernel_size ** 3
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d.conv_transpose3d_forward_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([]).to(x.device),
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation
        )
